<script setup lang="ts">
import { ref,onMounted } from 'vue'
import { api,post,bytes,user } from '../api'
const hidden=ref(false)
const path=ref(''),items=ref<any[]>([]),error=ref(''),busy=ref(false),offset=ref(0),progress=ref<number|null>(null),filter=ref('')
const full=(name:string)=>[path.value,name].filter(Boolean).join('/')
async function load(){try{items.value=await api(`files?path=${encodeURIComponent(path.value)}&hidden=${hidden.value}&offset=${offset.value}&q=${encodeURIComponent(filter.value)}`);error.value=''}catch(e){error.value=String(e)}}
function enter(name:string){path.value=full(name);offset.value=0;load()}
function up(){path.value=path.value.split('/').slice(0,-1).join('/');offset.value=0;load()}
async function action(name:string,action:string){const target=action==='move'||action==='copy'?prompt('目标路径（相对于文件根目录）',full(name)):'';if(target===null)return;if(action==='delete'&&!confirm(`永久删除 ${name}？此操作不可恢复。`))return;try{await post('files?path='+encodeURIComponent(full(name)),{Action:action,Target:target,Confirm:action==='delete'});await load()}catch(e){error.value=String(e)}}
async function mkdir(){const name=prompt('新目录名称');if(!name)return;try{await post('files?path='+encodeURIComponent(full(name)),{Action:'mkdir',Target:'',Confirm:false});load()}catch(e){error.value=String(e)}}
async function upload(event:Event){const input=event.target as HTMLInputElement;if(!input.files)return;busy.value=true;try{for(const file of Array.from(input.files)){if(file.size>100*1024*1024)throw new Error('单文件不能超过 100 MB');const exists=items.value.some(i=>i.name===file.name);if(exists&&!confirm(`覆盖 ${file.name}？`))continue;await new Promise<void>((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('PUT','/api/files?path='+encodeURIComponent(full(file.name))+(exists?'&overwrite=true':''));xhr.setRequestHeader('X-CSRF-Token',user.value!.csrf);xhr.upload.onprogress=e=>progress.value=e.lengthComputable?Math.round(e.loaded/e.total*100):0;xhr.onload=()=>xhr.status<300?resolve():reject(new Error(xhr.responseText));xhr.onerror=()=>reject(new Error('上传失败'));xhr.send(file)})}await load()}catch(e){error.value=String(e)}finally{busy.value=false;progress.value=null;input.value=''}}
onMounted(load)
</script>
<template><section class="card"><div class="toolbar"><button @click="up" :disabled="!path">↑ 上级</button><strong>/{{path}}</strong><input v-model="filter" placeholder="筛选文件名" @input="offset=0;load()"><label class="check"><input v-model="hidden" type="checkbox" @change="offset=0;load()">显示隐藏文件</label><button @click="mkdir">新建目录</button><label class="button primary">{{busy?'上传中 '+progress+'%':'上传文件'}}<input type="file" multiple hidden :disabled="busy" @change="upload"></label></div><p v-if="error" class="error">{{error}}</p><div class="table-wrap"><table><thead><tr><th>名称</th><th>大小</th><th>权限</th><th>修改时间</th><th>操作</th></tr></thead><tbody><tr v-for="f in items" :key="f.name"><td><button v-if="f.directory" class="text-button" @click="enter(f.name)">▱ {{f.name}}</button><a v-else :href="'/api/files?path='+encodeURIComponent(full(f.name))">▤ {{f.name}}</a></td><td>{{f.directory?'—':bytes(f.size)}}</td><td><code>{{f.mode}}</code></td><td>{{new Date(f.modified).toLocaleString()}}</td><td><button class="quiet" @click="action(f.name,'move')">移动/重命名</button><button class="quiet" @click="action(f.name,'copy')">复制</button><button class="quiet danger" @click="action(f.name,'delete')">删除</button></td></tr></tbody></table></div><div v-if="!items.length" class="empty">目录为空或无匹配文件</div><div class="pagination"><button :disabled="offset===0" @click="offset=Math.max(0,offset-50);load()">上一页</button><span>{{offset+1}}–{{offset+items.length}}</span><button :disabled="items.length<50" @click="offset+=50;load()">下一页</button></div><p class="muted small">目录内文件按扫描顺序分页。删除不可恢复；符号链接不能越过管理员配置的文件根目录。</p></section></template>
